import bpy,json,re,collections
c=bpy.data.collections['Shipyard_COMBINED_Craft']
plants=[]
for o in c.objects:
 if o.type=='MESH' and o.data.materials and any(t in o.data.materials[0].name for t in ['SageLeaf','SaltBush']):
  plants.append(o.name)
names=collections.Counter(re.sub(r'\.\d+$','',n) for n in plants)
samples=[]
for o in c.objects:
 if o.name.startswith('Steel roof panel') and o.type=='MESH' and o.data.materials[0].name=='SP13_WeatheredBlueSteel':
  uv=o.data.uv_layers.active;samples.append({'name':o.name,'uv_min':[min(t.uv[i] for t in uv.data) for i in range(2)],'uv_max':[max(t.uv[i] for t in uv.data) for i in range(2)]})
m=bpy.data.materials['SP13_WeatheredBlueSteel']
print(json.dumps({'plants':names,'roof_uv':samples[:12],'images':[(n.image.name,list(n.image.size),n.image.filepath) for n in m.node_tree.nodes if n.type=='TEX_IMAGE' and n.image]},ensure_ascii=False))
